// Actual original HEADS loaded scale getters, head references and XML adapter.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.awt.geom.*;
public class StemHeadReferenceContextProbe extends StemPartsLookupProbe {
 private final Object book;public StemHeadReferenceContextProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static String scale(Object value)throws Exception{List<String>rows=new ArrayList<>();for(String shape:new String[]{"NOTEHEAD_VOID","NOTEHEAD_BLACK"})for(String side:new String[]{"LEFT","RIGHT"})rows.add("{\"shape\":\""+shape+"\",\"side\":\""+side+"\",\"dx\":"+(value==null?"null":call(value,"getDx",en("glyph.Shape",shape),en("util.HorizontalSide",side)))+"}");return "["+String.join(",",rows)+"]";}
 static String number(Double d){return d==null?"null":d.toString();}
 public void process(){try{
 Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet"),scale=call(sheet,"getScale"),headScale=call(scale,"getHeadSeedScale");String before=scale(headScale);List<String>rows=new ArrayList<>();
 for(Object sys:(List<?>)call(sheet,"getSystems")){Object sig=call(sys,"getSig");List<?> heads=(List<?>)sig.getClass().getMethod("inters",Class.class).invoke(sig,Class.forName("org.audiveris.omr.sig.inter.HeadInter"));for(Object h:heads)for(String side:new String[]{"LEFT","RIGHT"})for(String vert:new String[]{"TOP","BOTTOM"}){Point2D p=(Point2D)call(h,"getStemReferencePoint",en("util.HorizontalSide",side),en("util.VerticalSide",vert));rows.add("{\"system\":"+call(sys,"getId")+",\"shape\":\""+call(h,"getShape")+"\",\"bounds\":"+rect(call(h,"getBounds"))+",\"side\":\""+side+"\",\"vertical\":\""+vert+"\",\"point\":["+p.getX()+","+p.getY()+"]}");}}
 Object adapter=Class.forName("org.audiveris.omr.util.Jaxb$Double1Adapter").getConstructor().newInstance();java.lang.reflect.Method marshal=adapter.getClass().getMethod("marshal",Double.class),unmarshal=adapter.getClass().getMethod("unmarshal",String.class);Object nf=get(adapter,"nf");List<Double> values=new ArrayList<>();values.add(null);values.add(0.);values.add(-0.);for(int i=-64;i<=64;i++){double d=i/20.;values.add(Math.nextDown(d));values.add(d);values.add(Math.nextUp(d));}values.add(1./3.);values.add(-1./3.);values.add(1./7.);values.add(-1./7.);List<String>codec=new ArrayList<>();
 for(Double raw:values){String xml=(String)marshal.invoke(adapter,raw);Double restored=(Double)unmarshal.invoke(adapter,xml);codec.add("{\"raw\":"+number(raw)+",\"xml\":"+(xml==null?"null":"\""+xml+"\"")+",\"restored\":"+number(restored)+",\"restored_bits\":"+(restored==null?"null":"\""+Long.toHexString(Double.doubleToRawLongBits(restored))+"\"")+"}");}
 Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"loaded_HEADS_scale_before\":"+before+",\"loaded_HEADS_scale_after_reference_reads\":"+scale(call(scale,"getHeadSeedScale"))+",\"rounding_mode\":\""+call(nf,"getRoundingMode")+"\",\"maximum_fraction_digits\":"+call(nf,"getMaximumFractionDigits")+",\"minimum_fraction_digits\":"+call(nf,"getMinimumFractionDigits")+",\"grouping_used\":"+call(nf,"isGroupingUsed")+",\"head_references\":["+String.join(",",rows)+"],\"XML_adapter_controls\":["+String.join(",",codec)+"]}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
